using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Unity.Profiling;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using IslandGame;using IslandGame.Diorama;using Newtonsoft.Json.Linq;
public static class MeasureApprovedPreview {
 const string Dir="C:/Users/SHK/island-contact-diorama-20261107/evidence/";
 public static object Main(){IslandGame.Editor.BattleHudReview.SetSize(1080,1920);var w=EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView"));w.Focus();Application.runInBackground=true;EditorApplication.isPaused=false;var s=UnityEngine.Object.FindFirstObjectByType<DioramaPreviewStage>();s.StartCoroutine(Run(s,w));return new{started=true,expectedSeconds=78};}
 static IEnumerator Run(DioramaPreviewStage s,EditorWindow w){var results=new JArray();var errors=new List<string>();Application.LogCallback cb=(m,stack,t)=>{if(t==LogType.Error||t==LogType.Exception)errors.Add(m);};Application.logMessageReceived+=cb;s.GetComponent<DioramaPreviewControls>().visible=false;s.surface=DioramaSurface.SoftNilo;s.depthOfField=s.vignette=s.outline=s.rim=false;
  foreach(bool bloom in new[]{false,true})foreach(DioramaView view in Enum.GetValues(typeof(DioramaView))){s.shot=view;s.bloom=bloom;s.animate=false;s.ResetSample();s.RefreshLook();s.volume.profile.TryGet<Bloom>(out var b);b.threshold.Override(1.15f);b.intensity.Override(.10f);b.clamp.Override(2);b.scatter.Override(.4f);double start=Time.realtimeSinceStartupAsDouble;while(Time.realtimeSinceStartupAsDouble-start<5){w.Repaint();yield return null;}if(bloom){ScreenCapture.CaptureScreenshot(Dir+"approved-"+view+".png");yield return null;}
   typeof(IslandBudgetPolicy).GetProperty("Level").SetValue(IslandFrameBudget.Current.Policy,0);s.animate=true;s.ResetSample();var rows=new List<double[]>();var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");start=Time.realtimeSinceStartupAsDouble;double prev=start;int quality=0;while(Time.realtimeSinceStartupAsDouble-start<8){w.Repaint();yield return null;double now=Time.realtimeSinceStartupAsDouble;var budget=IslandFrameBudget.Current;rows.Add(new[]{(now-prev)*1000,budget.CpuActiveMilliseconds,budget.GpuMilliseconds,gc.Valid?(double)gc.LastValue:-1,UnityStats.drawCalls,UnityStats.setPassCalls});prev=now;quality=Math.Max(quality,budget.Policy.Level);}gc.Dispose();results.Add(new JObject{["view"]=view.ToString(),["bloom"]=bloom,["samples"]=rows.Count,["frameMs"]=Stats(rows.Select(r=>r[0])),["cpuMs"]=Stats(rows.Select(r=>r[1])),["gpuDiagnosticMs"]=Stats(rows.Select(r=>r[2])),["gcBytes"]=Stats(rows.Select(r=>r[3])),["drawCalls"]=Stats(rows.Select(r=>r[4])),["setPass"]=Stats(rows.Select(r=>r[5])),["maxAdaptiveQualityLevel"]=quality});File.WriteAllText(Dir+"approved-cost-progress.json",results.ToString());
  }s.animate=false;s.GetComponent<DioramaPreviewControls>().visible=true;Application.logMessageReceived-=cb;File.WriteAllText(Dir+"approved-cost.json",new JObject{["approvedSurface"]="SoftNilo",["bloomIntensity"]=.1,["threshold"]=1.15,["depthOfField"]=false,["vignette"]=false,["runs"]=results,["errors"]=new JArray(errors)}.ToString());
 }
 static JObject Stats(IEnumerable<double> values){var a=values.OrderBy(x=>x).ToArray();return new JObject{["mean"]=a.Average(),["p95"]=a[(int)((a.Length-1)*.95)],["p99"]=a[(int)((a.Length-1)*.99)],["max"]=a.Last()};}
}
